# Generated by manage.py generate_test_cases.
import json

from django.contrib.contenttypes.models import ContentType
from django.http import HttpResponse

from bloomerp.models.project_management.todo import Todo, TodoPriority, TodoStatus
from bloomerp.tests.base import (
    BloomerpComponentTestCase,
    ExpectedResult,
    RequestScenario,
)


class TestCreateTodoForObjectComponent(BloomerpComponentTestCase):
    """Tests function `create_todo_for_object` from `bloomerp/components/todos/create_todo_for_object.py`."""

    view_name = 'components_create_todo_for_object'

    def get_test_scenarios(self) -> list[RequestScenario]:
        """Cover successful dialog completion and validation without navigation."""
        content_type = ContentType.objects.get_for_model(self.CustomerModel)
        customer = self.create_customer("Todo", "Owner", 30)
        self.todo_owner_id = str(customer.pk)
        kwargs = {"content_type_id": content_type.pk, "object_id": str(customer.pk)}
        return [
            RequestScenario(
                name="Todo form targets its own modal body",
                user=self.admin_user,
                view_kwargs=kwargs,
                headers={"hx-request": "true"},
                expected=ExpectedResult(response_validators=[
                    self.contains_text('hx-target="closest [data-modal-body]"'),
                ]),
            ),
            RequestScenario(
                name="Successful todo creation closes the modal with immediate feedback",
                method="POST",
                user=self.admin_user,
                view_kwargs=kwargs,
                headers={"hx-request": "true"},
                data={"title": "Modal todo", "priority": TodoPriority.MEDIUM,
                      "status": TodoStatus.BACKLOG, "content_type": str(content_type.pk),
                      "object_id": str(customer.pk)},
                expected=ExpectedResult(response_validators=[self.todo_modal_completed]),
            ),
            RequestScenario(
                name="Invalid todo keeps the form open with validation errors",
                method="POST",
                user=self.admin_user,
                view_kwargs=kwargs,
                headers={"hx-request": "true"},
                data={"title": "", "priority": TodoPriority.MEDIUM,
                      "status": TodoStatus.BACKLOG},
                expected=ExpectedResult(response_validators=[
                    self.contains_text('This field is required.'),
                    self.invalid_todo_remains_open,
                ]),
            ),
        ]

    def todo_modal_completed(self, response: HttpResponse) -> bool:
        """Verify creation emits a close event without a redirect or deferred message."""
        next_response = self.client.get(response.wsgi_request.path, HTTP_HX_REQUEST="true")
        return (
            json.loads(response["HX-Trigger"]) == {
                "bloomerp:close-modal": {"modalId": "detail-todo-modal"},
            }
            and "HX-Refresh" not in response
            and "Location" not in response
            and "Object successfully created" in response.content.decode()
            and "Object successfully created" not in next_response.content.decode()
            and Todo.objects.filter(
                title="Modal todo", object_id=self.todo_owner_id,
                content_type=ContentType.objects.get_for_model(self.CustomerModel),
            ).exists()
        )

    def invalid_todo_remains_open(self, response: HttpResponse) -> bool:
        """Ensure failed validation neither closes the modal nor navigates away."""
        return "HX-Trigger" not in response and "Location" not in response
